import{_ as a,o as e,c as n,ag as i}from"./chunks/framework.CxkNbRKf.js";const m=JSON.parse('{"title":"Manage studies","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/studies.md","filePath":"admin-guide/web-ui/studies.md","lastUpdated":1786379412000}'),d={name:"admin-guide/web-ui/studies.md"};function s(o,t,r,l,c,h){return e(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="manage-studies" tabindex="-1">Manage studies <a class="header-anchor" href="#manage-studies" aria-label="Permalink to &quot;Manage studies&quot;">​</a></h1><p>The <strong>Manage studies</strong> page — accessible via <strong>Studies → Manage studies</strong> in the administrator menu — is the central listing of all catalog entries. From here you can add, edit, publish, unpublish, and delete entries across all data types.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Manage studies list view showing entries with type, status, collection, and action buttons</em></p></div><h2 id="adding-and-managing-content-by-data-type" tabindex="-1">Adding and managing content by data type <a class="header-anchor" href="#adding-and-managing-content-by-data-type" aria-label="Permalink to &quot;Adding and managing content by data type&quot;">​</a></h2><p>Full instructions for adding and managing each data type are in the <strong><a href="/nada-documentation/admin-guide/content/">Managing content</a></strong> section:</p><table tabindex="0"><thead><tr><th>Data type</th><th>Documentation</th></tr></thead><tbody><tr><td>Microdata</td><td><a href="/nada-documentation/admin-guide/content/microdata.html">Adding microdata</a></td></tr><tr><td>Geospatial</td><td><a href="/nada-documentation/admin-guide/content/geospatial.html">Adding a geographic dataset</a></td></tr><tr><td>Indicators &amp; time series</td><td><a href="/nada-documentation/admin-guide/content/indicators.html">Adding an indicator / time series</a></td></tr><tr><td>Tables</td><td><a href="/nada-documentation/admin-guide/content/tables.html">Adding a table</a></td></tr><tr><td>Documents</td><td><a href="/nada-documentation/admin-guide/content/documents.html">Adding a document</a></td></tr><tr><td>Images</td><td><a href="/nada-documentation/admin-guide/content/images.html">Adding an image</a></td></tr><tr><td>Videos</td><td><a href="/nada-documentation/admin-guide/content/videos.html">Adding a video</a></td></tr><tr><td>Scripts</td><td><a href="/nada-documentation/admin-guide/content/scripts.html">Adding scripts</a></td></tr></tbody></table><h2 id="filtering-and-searching" tabindex="-1">Filtering and searching <a class="header-anchor" href="#filtering-and-searching" aria-label="Permalink to &quot;Filtering and searching&quot;">​</a></h2><p>The studies list can be filtered by data type, collection, publication status (draft / published), and country. Use the search box to find entries by title or ID.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Studies list with type and status filters applied</em></p></div><h2 id="batch-operations" tabindex="-1">Batch operations <a class="header-anchor" href="#batch-operations" aria-label="Permalink to &quot;Batch operations&quot;">​</a></h2><p>Select multiple entries to apply batch actions such as publish, unpublish, or move to a collection.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Batch action toolbar with entries selected</em></p></div><h2 id="entry-lifecycle" tabindex="-1">Entry lifecycle <a class="header-anchor" href="#entry-lifecycle" aria-label="Permalink to &quot;Entry lifecycle&quot;">​</a></h2><p>All catalog entries go through the same publishing lifecycle — draft, published, and archived — regardless of data type. See <a href="/nada-documentation/admin-guide/content/lifecycle.html">Entry lifecycle</a> for details on status transitions and visibility rules.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./collections.html">Collections</a> — organize entries into sub-catalogs</li><li><a href="./licensed-requests.html">Licensed requests</a> — manage access requests for restricted datasets</li><li><a href="./bulk-data-access.html">Bulk data access</a> — offer groups of datasets for bulk download</li></ul>',16)])])}const g=a(d,[["render",s]]);export{m as __pageData,g as default};
